  for each row execute function private.require_active_photo_write();

create or replace function private.require_active_photo_write() returns trigger
language plpgsql volatile security definer set search_path='' as $$
declare target storage.objects%rowtype; subject uuid; original_role text:=current_setting('role',true);
begin
 target:=case when tg_op='DELETE' then old else new end;
 if target.bucket_id='profile-photos' then
  if original_role='authenticated' then
   subject:=auth.uid();
   if subject is null or target.owner_id is distinct from subject::text then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
  elsif original_role='service_role' then
   -- Real Storage first checks client permission separately, then persists as
   -- supabase_storage_admin/service_role with auth.uid null. Guard that final
   -- row through commit using its server-assigned owner; no service RPC grant.
   if tg_op<>'INSERT' or session_user<>'supabase_storage_admin' or target.owner_id is null
    or target.owner_id !~ '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
   subject:=target.owner_id::uuid;
   -- Storage finalizes via UPSERT even for a create request. Never let its
   -- privileged final insert overwrite an already committed immutable name.
   if exists(select 1 from storage.objects o where o.bucket_id=target.bucket_id and o.name=target.name) then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
  end if;
  if original_role in ('authenticated','service_role') then
   if target.name !~ ('^'||subject::text||'/[a-f0-9-]+\.(jpg|png|webp)$') then
    raise exception 'Owner operation unavailable' using errcode='42501'; end if;
   perform private.pilot_lock_owner_evidence(subject);
  end if;
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $$;
revoke all on function private.require_active_profile_write(),private.require_active_photo_write() from public,anon,authenticated,service_role;
-- Supabase finalization uses privileged ON CONFLICT UPDATE. Reject UPDATE in
-- the database itself, including a raw owner INSERT that wins after the final
-- INSERT trigger's existence check. No advisory participation is assumed.
create function private.reject_client_profile_photo_update() returns trigger
language plpgsql volatile security definer set search_path='' as $$
begin
 if (old.bucket_id='profile-photos' or new.bucket_id='profile-photos')
  and current_setting('role',true) in ('authenticated','service_role') then
  raise exception 'Profile photos are immutable' using errcode='42501'; end if;
 return new;
end; $$;
revoke all on function private.reject_client_profile_photo_update() from public,anon,authenticated,service_role;
create trigger pals_reject_client_profile_photo_update before update on storage.objects
 for each row execute function private.reject_client_profile_photo_update();

create function private.protect_profile_photo_delete() returns trigger
language plpgsql security definer set search_path = '' as $$
declare profile public.profiles;
begin
 if old.bucket_id='profile-photos' then
   -- RLS NOT EXISTS alone has a stale statement snapshot race. Lock the profile
   -- and examine the returned current tuple, not a pre-lock snapshot. A newer
   -- tuple at REPEATABLE READ aborts. Lock inversion may abort, never orphan.
   select * into profile from public.profiles where user_id::text=old.owner_id for update;
   if found and (profile.primary_photo_path=old.name or old.name=any(profile.additional_photo_paths)) then
     raise exception 'Detach a profile photo before deleting it' using errcode='23514';
   end if;
 end if;
 return old;
end;
$$;
revoke all on function private.protect_profile_photo_delete() from public,anon,authenticated;
create trigger pals_protect_profile_photo_delete before delete on storage.objects
for each row execute function private.protect_profile_photo_delete();
